mapper.select:
SELECT m.id materialId,m.project_id projectId,t.id materialTypeId,t.code materialTypeCode,t.name materialTypeName,
  t.module_type moduleType,t.allowed_file_types allowedFileTypes,t.max_file_size_mb maxFileSizeMb,v.id materialVersionId,
  v.version_no versionNo,v.original_filename fileName,v.sha256 fileHash,v.uploaded_by uploadedBy,v.created_at uploadedAt,
  (v.file_status='ACTIVE') isCurrent FROM material m JOIN material_type t ON t.code=m.material_type_code
  JOIN material_version v ON v.material_id=m.id

  AND m.project_id=#{project}
  AND m.id=#{material}
  AND v.id=#{version}
  AND v.file_status<>'DELETED'
 ORDER BY m.id,v.version_no DESC
